+
+	if err != nil {
+		t.Errorf("Error decoding JSON: %s", err)
+	}
+
+	testClient := &common.TestClient{}
+	result.SetClient(testClient)
+
+
+	result.SupportedResetTypes = []ResetType{GracefulRestartResetType}
+	err = result.Reset(GracefulRestartResetType)
